KlpApplication.code:
final destination = KlpDestination<Object?, Object?>(KlpId.root('app'));
final router = KlpRouter(
	id: KlpId.root('router'),
	initial: destination.location(null),
	routes: [
		KlpRoute(destination, screen: (input) => screen),
	],
);
final application = KlpApplication(
	title: 'Example',
	primitives: KlpWorkspacePreset.light(),
	router: router,
);
runKlpApp(KlpMutableState(application).readOnly);

